  let(:owner) { timekeeping_arrange.user(company:, role: "owner") }
  let(:owner_token) { timekeeping_arrange.token_for(owner) }

  # "While fenced, Timekeeping refuses every entry write at every generation with stale_generation, including for a company it has never seen"
  it "refuses writes for an existing company carrying the old, the next and an empty generation while fenced and writes nothing" do
