# frozen_string_literal: true
require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "after re-admission" do
  include_context "timekeeping entry writes"

  let(:company) { timekeeping_arrange.company }
  let(:project) { timekeeping_arrange.project(company:) }
  let(:owner) { timekeeping_arrange.user(company:, role: "owner") }
  let(:owner_token) { timekeeping_arrange.token_for(owner) }

  # "After re-admission at a generation, only that generation is accepted"
  # Example from the issue: "After `admit!(generation: 4)`, a write carrying 4 succeeds and one carrying 3 is refused."
  # 5 is also refused, so the check is equality and not "at least".
  it "accepts only generation 4 after admit at 4 and stamps 4 on the outbox row" do
    entry_id = timekeeping_arrange.entry(company:, user: owner, project:)
    Timekeeping::Admission.fence!(lock_timeout: 1)
    Timekeeping::Admission.admit!(generation: 4)
    baseline = entry_write_counts

    [3, 5].each do |generation|
      patch = build_entry_command(:update, token: owner_token, entry_id:, generation:, body: { "note" => "Stale" })
      outcome = described_class.new.call(patch)

      expect([outcome.status, JSON.parse(outcome.body)]).to eq([409, { "reason" => "stale_generation" }])
      expect(entry_write_counts).to eq(baseline)
    end

    admitted = described_class.new.call(
      build_entry_command(:update, token: owner_token, entry_id:, generation: 4, body: { "note" => "Admitted" })
    )

    expect(admitted.status).to eq(200)
    expect(Entry.find(entry_id).note).to eq("Admitted")
    expect(OutboxSnapshot.where(company_id: company).pluck(:generation)).to eq([4])
  end
end

# frozen_string_literal: true
require "rails_helper"
require "webmock/rspec"

RSpec.describe Timekeeping::EntryWriter, "fence persistence" do
  include_context "timekeeping entry writes"

  let(:company) { timekeeping_arrange.company }
  let(:project) { timekeeping_arrange.project(company:) }
  let(:owner) { timekeeping_arrange.user(company:, role: "owner") }
  let(:owner_token) { timekeeping_arrange.token_for(owner) }

  # "The fence stays in place until a later admission"
  it "keeps the fence through refused writes until admit is called again" do
    entry_id = timekeeping_arrange.entry(company:, user: owner, project:)
    Timekeeping::Admission.fence!(lock_timeout: 1)

    3.times do
      outcome = described_class.new.call(
        build_entry_command(:update, token: owner_token, entry_id:, generation: 1, body: { "note" => "Fenced" })
      )
      expect(JSON.parse(outcome.body)).to eq("reason" => "stale_generation")
      expect(Timekeeping::Admission.current.generation).to be_nil
    end

    Timekeeping::Admission.admit!(generation: 2)
    outcome = described_class.new.call(
      build_entry_command(:update, token: owner_token, entry_id:, generation: 2, body: { "note" => "Open" })
    )

    expect(outcome.status).to eq(200)
    expect(Timekeeping::Admission.current.generation).to eq(2)
  end
end

